/**
 * Story 378 (pwa-activity-07): a `<dialog>` keeps its returnValue across a reopen, and Escape or
 * Android back closes it without setting a new one. After one Save, dismissing the dialog ran the
 * save path again with whatever had been typed. Every open starts from no answer.
 */
export function showModalFresh(dialog: HTMLDialogElement): void {
    dialog.returnValue = '';
    dialog.showModal();
}
